import{_ as r,o as s,c as o,j as e,a as i,aa as a}from"./chunks/framework.BAs_AphD.js";const g=JSON.parse('{"title":"User Permissions","description":"","frontmatter":{"title":"User Permissions","wiki":"en:diary:userpermissions"},"headers":[],"relativePath":"en/diary/userpermissions.md","filePath":"en/diary/userpermissions.md","lastUpdated":1793088561000}'),n={name:"en/diary/userpermissions.md"};function d(l,t,h,c,m,p){return s(),o("div",null,[...t[0]||(t[0]=[e("h1",{id:"user-permissions",tabindex:"-1"},[i("User Permissions "),e("a",{class:"header-anchor",href:"#user-permissions","aria-label":'Permalink to "User Permissions"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/akZLFxBlluo",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),a('<p>The user permission system in <strong>Buildary.online (hereinafter referred to as &quot;Buildary&quot;)</strong> is designed to allow straightforward work on smaller projects with small project teams. At the same time, it is flexible enough to meet the requirements of large corporate customers and project teams, even on the largest construction projects.</p><p>The user permission system in Buildary can be viewed as having three levels.</p><p><strong>The first level of permissions is at the domain level</strong> and determines whether a user can administer the domain, create and manage new projects and diaries within that domain. These permissions are assigned to users by the domain administrator. For users working in their personal domain, this level is irrelevant because they always have full permissions in their personal domain.</p><p><strong>The second level of permissions is at the project level</strong>, where company roles and member roles and their permissions for the project can be defined for the entire project team.</p><p><strong>The third level is the Project Diary and its records.</strong> For each Project Diary, authorized persons from the project team and their roles are defined. Users&#39; permissions within the diary are determined by these roles. The Authorized Persons section of the diary contains predefined roles from the project team, but the role can be changed at the diary level, allowing an authorized person to have a different role in each diary if required. This is the level that every diary administrator must understand and use correctly.</p><h2 id="domain-users" tabindex="-1">Domain Users <a class="header-anchor" href="#domain-users" aria-label="Permalink to &quot;Domain Users&quot;">​</a></h2><p>Users who only work on projects to which they have been invited, as well as users who only work in their personal domain, do not need to manage domain permissions.</p><p>For a corporate domain administrator, however, it is important to correctly understand and configure permissions at the domain level. The domain user list should contain only employees of the company, not external users. External users are added as <strong>Project Team Members</strong> on specific projects.</p><p>The following permission areas can be assigned to domain users:</p><ul><li><p><strong>Domain Administration</strong> – allows the user to edit domain information and settings, add domain users including configuring their permissions, and delete the domain. It also allows the user to view all projects in the domain, but does not grant permission to edit them. The domain administrator can create <strong>Template Projects</strong> and modify their settings, including the default code lists.</p></li><li><p><strong>Project Creation</strong> – allows the user to create new projects within the domain.</p></li><li><p><strong>Project Management</strong> – allows the user, on projects where they are a project team member, to edit project information, add companies and Project Team Members to the project, and create new Project Diaries.</p></li><li><p><strong>Administrator of All Projects and Diaries in the Domain</strong> – allows the user to manage all projects in the domain, regardless of who created them. This includes adding organizations and team members, modifying role code lists, creating and configuring diaries, and editing the cover sheet and Authorized Persons in the Identification Details. Assigning this role gives the user read-only access to Daily Records. This role does not grant permission to enter Daily Records or add Basic Documents, Project Documentation, Inspections and Tests, or other documents.</p></li><li><p><strong>Reader of All Projects</strong> – allows access to all diaries in the domain without the ability to make any changes to them.</p></li></ul><p>When a domain is created, its creator is automatically added to the domain users as an administrator. In addition, the user who created the domain and thereby became its owner has the same permissions as the domain administrator by virtue of being the owner. Therefore, deleting the domain user or changing their permissions cannot restrict the domain owner&#39;s permissions.</p><p>After a user is added to a domain, an invitation is sent to their email address asking them to create an account. The user account and the user in the domain are linked based on the email address, regardless of which one was created first.</p><h2 id="project-users" tabindex="-1">Project Users <a class="header-anchor" href="#project-users" aria-label="Permalink to &quot;Project Users&quot;">​</a></h2><p>If you have created a project and want to give other users access to it, you must first add them as <strong>Project Team Members</strong>. This is done in the project settings under <strong>Project Team</strong>.</p><p>After a user is added as a project team member, an invitation is sent to their email address.</p><p>Adding a user as a project team member gives them access to the project, but does not by itself grant them any permissions to work with the Project Diary. These must be defined by selecting the appropriate role based on the user&#39;s actual role on the project when adding or editing the project team member. The roles assigned to project members determine what permissions the user has in the Project Diary.</p><h3 id="authorized-persons-in-the-diary" tabindex="-1">Authorized Persons in the Diary <a class="header-anchor" href="#authorized-persons-in-the-diary" aria-label="Permalink to &quot;Authorized Persons in the Diary&quot;">​</a></h3><p><strong>Permission Area - Project Diary:</strong></p><ul><li><p><strong>Diary Administration</strong> – allows the user to edit the diary&#39;s Identification Details, add Authorized Persons, and delete the diary (only if it does not contain signed and locked Daily Reports). It also allows the user to perform all diary configurations available under <strong>Diary Settings</strong>.</p></li><li><p><strong>Regular Entries</strong> – allows the user to add, edit, and delete records in the Weather, Persons, Machinery, Materials, and Performed Works sections. However, only their own records can be edited or deleted, and only until the day is locked.</p></li><li><p><strong>Other Entries</strong> – allows the user to add, edit, and delete records in the Additional Records section. However, only their own records can be edited or deleted, and only until the record is locked.</p></li><li><p><strong>Project Documents</strong> – allows the user to add, edit, and delete records in the Documents section of the Project Diary&#39;s Identification Details, i.e. Basic Documents, Project Documentation, Inspections and Tests, and Other Documents.</p></li></ul><p>When a diary is created, its creator is automatically added to the Authorized Persons as an administrator. In addition, the user who created the diary and thereby became its owner has the same permissions as the diary administrator by virtue of being the owner. Therefore, deleting the user or changing their role cannot restrict the diary owner&#39;s permissions.</p><p><strong>Permission Area - Project:</strong></p><ul><li><strong>Project Administration</strong> – allows the user to expand the project&#39;s project team and modify project settings, including code lists and drawings for the Project Diary. Some permissions within this area can be assigned separately through sub-areas: <ul><li><strong>Project Team Administration</strong> – allows the user to add a new project team member, create a new company on the project, and add an Authorized Person to the Project Diary.</li><li><strong>Project Completion</strong> – allows the user to close the project.</li><li><strong>New Diary by Copy</strong> – allows the user to create a new diary by copying an existing diary.</li></ul></li></ul><h2 id="diary-users" tabindex="-1">Diary Users <a class="header-anchor" href="#diary-users" aria-label="Permalink to &quot;Diary Users&quot;">​</a></h2><p>If a user is to have access to a diary, they must be added to the diary&#39;s list of <strong>Authorized Persons</strong>. This is done in the diary&#39;s <strong>Identification Details</strong>. The user is also assigned a role inherited from <strong>Project Team Members</strong>, which can be changed as needed for each diary. Their permissions to work in the diary are then determined by this role.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If a user is listed as an Authorized Person in a diary, they have access to the entire Project Diary for viewing, regardless of their role. This right is established by law, and the Buildary system respects it.</p></div>',25)])])}const y=r(n,[["render",d]]);export{g as __pageData,y as default};
